// Hand-written. Not generated by Speakeasy.
//
// The companion to the PublicJWKS custom type. The type validates the
// configuration, which is where the error is most useful: it names the file
// and fires before anything is sent.
//
// It cannot see a value the configuration does not hold yet. A client's jwks
// built from a tls_private_key reference is unknown at plan time, so attribute
// validation skips it and the mistake reaches Authlete, which strips the
// private half without reporting an error and leaves the plan never settling.
//
// Terraform re-plans during apply with the value resolved, so a plan modifier
// gets a second look that attribute validation does not. This runs the same
// check then.
package planmodifiers

import (
	"context"

	"github.com/hashicorp/terraform-plugin-framework/attr/xattr"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/planmodifier"
)

// RefusePrivateKeysInJWKS returns a plan modifier that applies a JWK Set
// attribute's own validation to the planned value.
func RefusePrivateKeysInJWKS() planmodifier.String { return refusePrivateKeysInJWKS{} }

type refusePrivateKeysInJWKS struct{}

func (m refusePrivateKeysInJWKS) Description(_ context.Context) string {
	return "refuses a private or symmetric key in a client's JWK Set, including one " +
		"whose value is not known until apply"
}

func (m refusePrivateKeysInJWKS) MarkdownDescription(ctx context.Context) string {
	return m.Description(ctx)
}

func (m refusePrivateKeysInJWKS) PlanModifyString(ctx context.Context, req planmodifier.StringRequest, resp *planmodifier.StringResponse) {
	// Still unknown: this is the ordinary plan, and apply will come back here.
	if req.PlanValue.IsNull() || req.PlanValue.IsUnknown() {
		return
	}

	// Only what the practitioner wrote. A value read back from Authlete has
	// already had its private members stripped, so checking it would report
	// the server's own output as an error.
	if req.ConfigValue.IsNull() {
		return
	}

	validateable, ok := any(req.PlanValue).(xattr.ValidateableAttribute)
	if !ok {
		return
	}

	vResp := &xattr.ValidateAttributeResponse{}
	validateable.ValidateAttribute(ctx, xattr.ValidateAttributeRequest{Path: req.Path}, vResp)
	resp.Diagnostics.Append(vResp.Diagnostics...)
}
